// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

library DiceMath {
    function valid(uint8 mode, uint8 target) internal pure returns (bool) {
        return mode == 0 ? target <= 1 : mode == 1 ? target >= 3 && target <= 18 : mode == 2 && target == 0;
    }

    function prize(uint8 mode, uint8 target) internal pure returns (uint256) {
        require(valid(mode, target), "Invalid choice");
        if (mode == 0) return 100;
        if (mode == 2) return 1500;
        uint16[19] memory payouts = [uint16(0),0,0,5000,1600,800,500,350,250,200,180,180,200,250,350,500,800,1600,5000];
        return payouts[target];
    }

    function faces(bytes32 word) internal pure returns (uint8[3] memory values) {
        for (uint32 die; die < 3; ++die) {
            bool found;
            for (uint32 attempt; attempt < 16 && !found; ++attempt) {
                bytes32 digest = sha256(abi.encodePacked("PLAYROOM:DICE:v1:", word, die, attempt));
                for (uint256 j; j < 32; ++j) {
                    uint8 sample = uint8(digest[j]);
                    if (sample < 252) { values[die] = sample % 6 + 1; found = true; break; }
                }
            }
            require(found, "Mapping exhausted");
        }
    }

    function outcome(uint8[3] memory values, uint8 mode, uint8 target) internal pure returns (uint256 amount) {
        bool triple = values[0] == values[1] && values[1] == values[2];
        uint256 sum = uint256(values[0]) + values[1] + values[2];
        bool won = mode == 2 ? triple : mode == 1 ? sum == target : !triple && (target == 0 ? sum >= 4 && sum <= 10 : sum >= 11 && sum <= 17);
        return won ? prize(mode, target) : 0;
    }
}

