// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {VRFConsumerBaseV2} from "./vendor/chainlink/src/v0.8/vrf/VRFConsumerBaseV2.sol";
import {IVRFCoordinatorV2Plus} from "./vendor/chainlink/src/v0.8/vrf/dev/interfaces/IVRFCoordinatorV2Plus.sol";
import {VRFV2PlusClient} from "./vendor/chainlink/src/v0.8/vrf/dev/libraries/VRFV2PlusClient.sol";
import {DiceMath} from "./DiceMath.sol";

/// @notice Testnet-only, non-transferable demo points. No deposits or withdrawals.
/// @dev Uses the official immutable V2 callback gate with the V2.5 request API.
/// Both coordinators call rawFulfillRandomWords(uint256,uint256[]). Deliberately
/// excludes V2Plus's owner/coordinator migration hook; deploy a new version instead.
contract DiceVRF is VRFConsumerBaseV2 {
    uint256 public constant COST = 50;
    bytes32 public constant RULES_HASH = 0x737a12bac5af9ec73c383a650c74650909ca2c9c7fa8790da1ea6fbfec8cd9fa;
    address public immutable coordinator;
    uint256 public immutable subscriptionId;
    bytes32 public immutable keyHash;
    uint16 public immutable confirmations;
    uint32 public immutable callbackGasLimit;
    bool public immutable nativePayment;

    struct Round {
        address player;
        uint8 mode;
        uint8 target;
        uint8 state; // 1=requested, 2=randomness ready, 3=settled
        uint256 nonce;
        uint256 requestId;
        bytes32 randomWord;
        uint256 amount;
    }
    mapping(uint256 => Round) public rounds;
    mapping(uint256 => uint256) public requestToRound;
    mapping(address => uint256) public balances;
    mapping(address => uint256) public nonces;
    mapping(address => uint256) public activeRound;
    mapping(address => bool) public claimed;
    uint256 public roundCount;
    uint256 public availablePool = 10_000_000;
    uint256 public reservedPool;
    bool private entered;

    event RoundRequested(uint256 indexed roundId, address indexed player, uint256 indexed requestId, uint256 nonce, uint8 mode, uint8 target, bytes32 rulesHash);
    event RandomnessReady(uint256 indexed roundId, uint256 indexed requestId, bytes32 word);
    event RoundSettled(uint256 indexed roundId, address indexed player, uint8[3] values, uint256 amount);

    modifier nonReentrant() { require(!entered,"Reentrant"); entered=true; _; entered=false; }

    constructor(address coordinator_, uint256 subId_, bytes32 keyHash_, uint16 confirmations_, uint32 callbackGasLimit_, bool nativePayment_) VRFConsumerBaseV2(coordinator_) {
        require(block.chainid == 11155111 || block.chainid == 31337,"Testnet only");
        require(coordinator_.code.length > 0 && subId_ > 0 && keyHash_ != bytes32(0),"Invalid VRF configuration");
        require(confirmations_ >= 3 && callbackGasLimit_ >= 100_000,"Unsafe VRF configuration");
        coordinator=coordinator_;subscriptionId=subId_;keyHash=keyHash_;
        confirmations=confirmations_;callbackGasLimit=callbackGasLimit_;nativePayment=nativePayment_;
    }

    function claimDemoPoints() external {
        require(!claimed[msg.sender],"Already claimed");
        claimed[msg.sender]=true;balances[msg.sender]=1000;
    }

    function startRound(uint8 mode, uint8 target, uint256 expectedNonce) external nonReentrant returns (uint256 id) {
        require(DiceMath.valid(mode,target),"Invalid choice");
        require(expectedNonce == nonces[msg.sender] + 1 && activeRound[msg.sender] == 0,"Stale or active round");
        require(balances[msg.sender] >= COST,"Insufficient points");
        uint256 reserve = DiceMath.prize(mode,target);
        require(availablePool + COST >= reserve,"Insufficient reward reserve");
        balances[msg.sender]-=COST;availablePool=availablePool+COST-reserve;reservedPool+=reserve;
        nonces[msg.sender]=expectedNonce;
        id=++roundCount;activeRound[msg.sender]=id;
        Round storage r=rounds[id];r.player=msg.sender;r.mode=mode;r.target=target;r.state=1;r.nonce=expectedNonce;
        uint256 requestId=IVRFCoordinatorV2Plus(coordinator).requestRandomWords(VRFV2PlusClient.RandomWordsRequest({
            keyHash:keyHash,subId:subscriptionId,requestConfirmations:confirmations,callbackGasLimit:callbackGasLimit,numWords:1,
            extraArgs:VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({nativePayment:nativePayment}))
        }));
        require(requestId!=0 && requestToRound[requestId]==0,"Duplicate request ID");
        r.requestId=requestId;requestToRound[requestId]=id;
        emit RoundRequested(id,msg.sender,requestId,expectedNonce,mode,target,RULES_HASH);
    }

    // Fixed bounded writes only. Settlement can be retried without redrawing RNG.
    function fulfillRandomWords(uint256 requestId,uint256[] memory words) internal override {
        uint256 id=requestToRound[requestId];
        if(id==0 || rounds[id].state!=1 || words.length!=1)return;
        Round storage r=rounds[id];r.randomWord=bytes32(words[0]);r.state=2;
        emit RandomnessReady(id,requestId,r.randomWord);
    }

    function settle(uint256 id) external nonReentrant {
        Round storage r=rounds[id];require(r.state==2,"Round not ready");
        uint8[3] memory values=DiceMath.faces(r.randomWord);
        uint256 amount=DiceMath.outcome(values,r.mode,r.target);
        uint256 reserve=DiceMath.prize(r.mode,r.target);
        r.state=3;r.amount=amount;activeRound[r.player]=0;
        reservedPool-=reserve;availablePool+=reserve-amount;balances[r.player]+=amount;
        emit RoundSettled(id,r.player,values,amount);
    }

    function preview(bytes32 word,uint8 mode,uint8 target) external pure returns(uint8[3] memory values,uint256 amount) {
        require(DiceMath.valid(mode,target),"Invalid choice");values=DiceMath.faces(word);amount=DiceMath.outcome(values,mode,target);
    }
}

